InputDecoration standardInputDecoration(
  String? labelText,
  FocusNode textFieldFocusNode,
  BuildContext context, {
  bool desktopMed = false,
}) {
  final isDesktop = Util.isDesktop;

  return InputDecoration(
    labelText: labelText == null ? null : goTr(context, labelText),
    fillColor: textFieldFocusNode.hasFocus
        ? Theme.of(context).extension<StackColors>()!.textFieldActiveBG
        : Theme.of(context).extension<StackColors>()!.textFieldDefaultBG,
    labelStyle: isDesktop
        ? desktopMed
              ? STextStyles.desktopTextExtraSmall(context).copyWith(
                  color: Theme.of(
                    context,
                  ).extension<StackColors>()!.textFieldDefaultText,
                )
              : STextStyles.desktopTextFieldLabel(context)
        : STextStyles.fieldLabel(context),
    hintStyle: isDesktop
        ? desktopMed
              ? STextStyles.desktopTextExtraSmall(context).copyWith(
                  color: Theme.of(
                    context,
                  ).extension<StackColors>()!.textFieldDefaultText,
                )
              : STextStyles.desktopTextFieldLabel(context)
        : STextStyles.fieldLabel(context),
    // A white field on the tinted page measures 1.08:1 — without a border the
    // control has no visible edge at all. The design's #E4E4E7 hairline is what
    // makes it readable as an input, and it is now also what gives the field
    // its rounded shape: the ClipRRect that used to do that was removed from
    // every call site, because it cropped the floating label.
    enabledBorder: _defaultFieldBorder(context),
    focusedBorder: _defaultFieldBorder(context),
    disabledBorder: _defaultFieldBorder(context),
    // The error states used to be InputBorder.none, so a field that failed
    // validation lost its outline — and with it its shape. That was survivable
    // only because every call site wrapped the field in a ClipRRect that
    // rounded the fill by hand. Those wrappers are gone (they cropped the
    // floating label in half), so the shape has to come from the decoration in
    // every state, not just the happy ones.
    errorBorder: _defaultFieldBorder(context),
    focusedErrorBorder: _defaultFieldBorder(context),
  );
}

OutlineInputBorder _defaultFieldBorder(BuildContext context) =>
    OutlineInputBorder(
      borderRadius: BorderRadius.circular(Constants.size.circularBorderRadius),
      borderSide: BorderSide(
        color: Theme.of(
          context,
        ).extension<StackColors>()!.textFieldDefaultBorder,
        width: 1,
      ),
    );

class FullTextField extends StatefulWidget {
  const FullTextField({
    super.key,
    this.controller,
    this.focusNode,
    required this.label,
    this.onChanged,
  });

  final String label;

  final TextEditingController? controller;
  final FocusNode? focusNode;

  final void Function(String)? onChanged;

  @override
  State<FullTextField> createState() => _FullTextFieldState();
}

class _FullTextFieldState extends State<FullTextField> {
  late final TextEditingController controller;
  late final FocusNode focusNode;

  bool _hasValue = false;

  @override
  void initState() {
    super.initState();
    controller = widget.controller ?? TextEditingController();
    focusNode = widget.focusNode ?? FocusNode();
  }

  @override
  void dispose() {
    if (widget.controller == null) {
      controller.dispose();
    }
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return TextField(
      controller: controller,
      autocorrect: false,
      enableSuggestions: false,
      onChanged: (newValue) {
        widget.onChanged?.call(newValue);
      },
      focusNode: focusNode,
      style: STextStyles.field(context),
      decoration: standardInputDecoration(widget.label, focusNode, context)
          .copyWith(
            contentPadding: const EdgeInsets.only(
              left: 16,
              top: 6,
              bottom: 8,
              right: 5,
            ),
            suffixIcon: Padding(
              padding: controller.text.isEmpty
                  ? const EdgeInsets.only(right: 8)
                  : const EdgeInsets.only(right: 0),
              child: UnconstrainedBox(
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.spaceAround,
                  children: [
                    TextFieldIconButton(
                      onTap: () async {
                        if (_hasValue) {
                          controller.text = "";

                          setState(() {
                            _hasValue = false;
                          });
                        } else {
                          final data = await Clipboard.getData(
                            Clipboard.kTextPlain,
                          );
                          if (data?.text != null && data!.text!.isNotEmpty) {
                            final content = data.text!.trim();

                            controller.text = content;
                            setState(() {
                              _hasValue = content.isNotEmpty;
                            });
                          }
                        }

                        widget.onChanged?.call(controller.text);
                      },
                      child: _hasValue ? const XIcon() : const ClipboardIcon(),
                    ),
                  ],
                ),
              ),
            ),
          ),
    );
  }
}
